"""Retry helpers for calls to flaky downstream services."""
from __future__ import annotations

import random
import time
from typing import Callable, TypeVar

T = TypeVar("T")


class TransientError(Exception):
    """Raised by callers for errors that are safe to retry."""


def backoff(attempt: int, *, base: float = 0.5, cap: float = 8.0) -> float:
    """Exponential backoff without jitter: 1, 2, 4, 8, 8, ... seconds."""
    return min(cap, base * 2**attempt)


def call_with_retry(
    fn: Callable[[], T],
    *,
    deadline: float,
    clock: Callable[[], float] = time.monotonic,
    sleep: Callable[[float], None] = time.sleep,
    rng: random.Random | None = None,
) -> T:
    """Call fn until it succeeds or the next sleep would pass the deadline."""
    rng = rng or random.Random()
    start = clock()
    attempt = 0
    while True:
        try:
            return fn()
        except TransientError:
            attempt += 1
            delay = backoff(attempt)
            if clock() - start + delay > deadline:
                raise
            sleep(delay + rng.uniform(0, 0.25 * delay))

